{"path": "wordy.py", "content": "import operator

OPERATIONS = {
    "plus": operator.add,
    "minus": operator.sub,
    "multiplied by": operator.mul,
    "divided by": operator.floordiv,
}


def _is_number(token):
    try:
        int(token)
    except ValueError:
        return False
    return True


def answer(question):
    prefix = "What is"
    if not question.startswith(prefix):
        raise ValueError("unknown operation")

    words = question[len(prefix):].strip().rstrip("?").split()

    # Combine two-word operators and validate vocabulary.
    tokens = []
    index = 0
    while index < len(words):
        word = words[index]
        if word in ("multiplied", "divided") and index + 1 < len(words) and words[index + 1] == "by":
            word = f"{word} by"
            index += 1
        if not _is_number(word) and word not in OPERATIONS:
            raise ValueError("unknown operation")
        tokens.append(word)
        index += 1

    # Expect: number (operator number)*
    if not tokens or len(tokens) % 2 == 0:
        raise ValueError("syntax error")
    for position, token in enumerate(tokens):
        expect_number = position % 2 == 0
        if expect_number != _is_number(token):
            raise ValueError("syntax error")

    result = int(tokens[0])
    for position in range(1, len(tokens), 2):
        operand = int(tokens[position + 1])
        op_name = tokens[position]
        if op_name == "divided by":
            if operand == 0:
                raise ValueError("syntax error")
            quotient = abs(result) // abs(operand)
            result = quotient if (result < 0) == (operand < 0) else -quotient
        else:
            result = OPERATIONS[op_name](result, operand)
    return result
